mapper.select:
select uv.*, um.origin_url, um.short_url from url_visit uv left join url_mapping um on um.id = uv.url_id
and uv.create_time >= #{params.beginDate}
and uv.create_time <= #{params.endDate}
and uv.url_id in (select id from url_mapping where short_url = #{params.shortUrl})
order by uv.id desc
